// ===== 反模式：按 CRUD 拆分 + 共享数据库 =====
// ❌ 这不是微服务，只是分布式单表操作
@Service
public class UserCrudService {
    public void create(UserDTO dto) { userRepo.save(dto); }
    public UserDTO read(Long id) { return userRepo.findById(id); }
    public void update(UserDTO dto) { userRepo.save(dto); }
    public void delete(Long id) { userRepo.deleteById(id); }
}

// ❌ 反模式：订单服务直接查用户数据库
@Service
public class OrderService {
    @Autowired
    private UserRepository userRepo; // 直接依赖用户服务的数据库！
}

// ===== 正确做法：按限界上下文拆分 =====
// 用户上下文 - 用户服务（拥有用户数据，暴露业务能力）
@Service
public class UserService {
    public UserId register(RegisterCmd cmd) {
        User user = User.create(cmd.getUsername(), cmd.getPassword());
        userRepo.save(user);
        return user.getId();
    }

    public UserProfile getProfile(UserId id) {
        return userRepo.findProfile(id);
    }
}

// 订单上下文 - 订单服务（拥有订单数据，跨上下文通过 Client）
@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final UserClient userClient;         // HTTP/gRPC，非 DB 直连
    private final InventoryClient inventoryClient;

    public OrderId createOrder(CreateOrderCmd cmd) {
        // 校验用户（同步 RPC，配超时和熔断）
        UserProfile user = userClient.getProfile(cmd.getUserId());
        if (!user.isValid()) throw new DomainException("用户无效");

        // 校验库存（同步 RPC）
        boolean available = inventoryClient.checkStock(cmd.getItems());
        if (!available) throw new DomainException("库存不足");

        // 只持久化订单聚合，不跨库写库存表或用户表
        Order order = Order.create(cmd);
        orderRepo.save(order);
        return order.getId();
    }
}
